"""A cache whose entries expire after a time to live; the least recently used is evicted when it is full."""
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl):
        self.capacity = capacity
        self.ttl = ttl
        self.now = 0
        self.d = OrderedDict()
        self.hits = 0
        self.misses = 0

    def tick(self, dt):
        self.now += dt
        self._expire()

    def _expire(self):
        for k in list(self.d):
            if self.d[k][1] <= self.now:
                del self.d[k]

    def put(self, k, v):
        self.d[k] = (v, self.now + self.ttl)
        self.d.move_to_end(k)
        while len(self.d) > self.capacity:
            self.d.popitem(last=False)

    def get(self, k, default=None):
        entry = self.d.get(k)
        if entry is None or entry[1] <= self.now:
            self.misses += 1
            return default
        self.hits += 1
        self.d.move_to_end(k)
        return entry[0]

    def counts(self):
        return (self.hits, self.misses)

    def keys(self):
        return list(self.d)

    def snapshot(self):
        return (list(self.d), self.hits, self.misses)

