    def __init__(self):
        self.heap = []
        self.pos = {}

    def size(self):
        return len(self.heap)

    def push(self, key, prio):
        if key in self.pos:
            self.update(key, prio)
            return
        self.heap.append([prio, key])
        self.pos[key] = len(self.heap) - 1
        self._up(len(self.heap) - 1)

    def peek(self):
        return self.heap[0][1] if self.heap else None

    def pop(self):
        if not self.heap:
            return None
        top = self.heap[0][1]
        self._swap(0, len(self.heap) - 1)
        self.heap.pop()
        del self.pos[top]
        if self.heap:
            self._down(0)
        return top

    def update(self, key, prio):
        i = self.pos[key]
        old = self.heap[i][0]
        self.heap[i][0] = prio
        if prio < old:
            self._up(i)
        else:
            self._down(i)

    def remove(self, key):
        i = self.pos[key]
        last = len(self.heap) - 1
        self._swap(i, last)
        self.heap.pop()
        del self.pos[key]
        if i < len(self.heap):
            self._up(i)
            self._down(i)

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]
        self.pos[self.heap[i][1]] = i
        self.pos[self.heap[j][1]] = j

    def _up(self, i):
        while i > 0:
            p = (i - 1) // 2
            if self.heap[i] < self.heap[p]:
                self._swap(i, p)
                i = p
            else:
                break

    def _down(self, i):
        n = len(self.heap)
        while True:
            c = 2 * i + 1
            if c >= n:
                break
            if c + 1 < n and self.heap[c + 1] < self.heap[c]:
                c += 1
            if self.heap[c] < self.heap[i]:
                self._swap(i, c)
                i = c
            else:
                break

    def summary(self):
        return (self.peek(), len(self.heap))

